function _fnorm(s){s=String(s||'');s=s.replace(/[()\[\]\/-]/g,' ');['พิเศษ','ธรรมดา','ไซซ์ใหญ่','ไซซ์เล็ก','โปรโมชั่น','เมนูแนะนำ','สูตรร้าน','โฮมเมด','ขายดี','แคลต่ำ','คลีน','เพื่อสุขภาพ','พร้อมทาน','จานเดียว','ออร์แกนิก'].forEach(function(w){s=s.split(w).join('');});s=s.replace(/\d+\s*(กรัม|g|ml|มล|ชิ้น|ลูก|จาน|ที่|แก้ว|กล่อง|ฟอง|ถ้วย)/g,'');return s.replace(/\s+/g,'').trim();}
function _fkw(n,list){for(var i=0;i<list.length;i++){if(n.indexOf(list[i][0])>-1)return list[i][1];}return null;}
function _parseMenu(raw){var n=_fnorm(raw);var a={norm:n};a.protein=_fkw(n,_PPROT)||'none';a.family=_fkw(n,_PFAM)||null;a.method=[];for(var i=0;i<_PMETH.length;i++){if(n.indexOf(_PMETH[i][0])>-1&&a.method.indexOf(_PMETH[i][1])<0)a.method.push(_PMETH[i][1]);}a.drink=_PDR.test(n);a.dessert=_PDE.test(n);if(a.drink&&!a.family)a.family='drink';if(a.dessert&&!a.family)a.family='dessert';a.ingredient=(!a.family&&!a.method.length&&!a.drink&&!a.dessert);return a;}
var _SOLID=['rice','rice_dish','fried_rice','noodle','pasta','curry','soup','salad','sandwich','burger','pizza','wrap','japanese'];
function _fscore(m,en){var ic=FI_ATTR[en];var s=0;var thn=_fnorm(FI_TH[en]||'');if(thn&&thn===m.norm)return 200;if(m.family&&ic.family){if(m.family===ic.family||(m.family==='rice'&&ic.family==='rice_dish')||(m.family==='rice_dish'&&ic.family==='fried_rice'))s+=35;else if(_SOLID.indexOf(m.family)>=0&&_SOLID.indexOf(ic.family)>=0&&m.family!==ic.family&&!(m.family==='rice'&&ic.family==='fried_rice'))s-=50;}if(m.protein!=='none'&&ic.protein!=='none'){if(m.protein===ic.protein||(m.protein==='seafood'&&['shrimp','squid','crab','fish','salmon'].indexOf(ic.protein)>=0))s+=30;else s-=60;}for(var j=0;j<m.method.length;j++){if(ic.method.indexOf(m.method[j])>=0)s+=20;}if(m.drink&&!ic.drink)s-=80;if(!m.drink&&ic.drink)s-=80;if(m.dessert&&!ic.dessert&&!ic.drink)s-=60;if(!m.dessert&&!m.drink&&ic.dessert)s-=40;if(!m.ingredient&&ic.ingredient)s-=40;if(m.ingredient&&ic.ingredient)s+=25;if(ic.prepared&&!m.ingredient)s+=6;if(ic.set)s-=6;return s;}
function _engineMatch(raw){var m=_parseMenu(raw);var best=null,bs=-1e9;for(var i=0;i<FI_NAMES.length;i++){if(FI_BLOCK[FI_NAMES[i]])continue;var sc=_fscore(m,FI_NAMES[i]);if(sc>bs){bs=sc;best=FI_NAMES[i];}}var cf=bs>=200?1:bs>=120?0.92:bs>=70?0.8:0.4;return {icon:best,score:bs,conf:cf};}
function _keywordMatch(raw){raw=String(raw||'');for(var i=0;i<FOOD_IMG.length;i++){if(raw.indexOf(FOOD_IMG[i][0])>-1)return FOOD_IMG[i][1];}return null;}
function _foodOver(){try{return JSON.parse(localStorage.getItem('iufit_food_icon_override')||'{}')||{};}catch(e){return {};}}
window.setFoodIconOverride=function(menu,iconEn){try{var o=_foodOver();if(iconEn)o[menu]=iconEn;else delete o[menu];localStorage.setItem('iufit_food_icon_override',JSON.stringify(o));_iuFoodCache={};}catch(e){}};
window._iuFoodReview=[];
var _iuFoodCache={};
function iuFoodResolve(raw){raw=String(raw||'');if(_iuFoodCache[raw])return _iuFoodCache[raw];var ov=_foodOver();var ic,src,conf;if(ov[raw]){ic=ov[raw];src='override';conf=1;}else if(FOOD_OVERRIDE[raw]){ic=FOOD_OVERRIDE[raw];src='override_g';conf=1;}else{var kw=_keywordMatch(raw);if(kw&&kw!=='healthy_meal_plate'){ic=kw;src='keyword';conf=0.85;}else{var em=_engineMatch(raw);if(em.score>=120){ic=em.icon;src='engine';conf=em.conf;}else{ic='healthy_meal_plate';src='fallback';conf=0.2;}}}
if(raw.indexOf('ไข่ดาว')>-1){if(ic==='stir_fried_basil_chicken'||ic==='stir_fried_basil_seafood'||ic==='spicy_basil_seafood')ic='pad_krapao_moo_kai_dao';else if({roasted_duck_rice:1,khao_man_gai:1,japanese_curry_rice:1,steamed_rice_bowl:1,egg_fried_rice:1,crab_fried_rice:1,brown_rice_bowl:1,white_rice_bowl:1,red_rice_bowl:1}[ic])ic='grilled_chicken_rice_with_fried_egg';}else{if(ic==='pad_krapao_moo_kai_dao')ic='stir_fried_basil_chicken';else if(ic==='grilled_chicken_rice_with_fried_egg')ic='roasted_duck_rice';}
if(FI_ATTR[ic]==null&&ic!=='healthy_meal_plate')ic='healthy_meal_plate';
var r={icon:ic,src:src,conf:conf};_iuFoodCache[raw]=r;if(conf<0.6&&window._iuFoodReview.length<500)window._iuFoodReview.push({menu:raw,icon:ic,conf:conf});return r;}
window.iuFoodResolve=iuFoodResolve;


